# -*- coding: utf-8 -*-
"""M8 — Retrieving aerosol altitude with passive sensors (study guide Ch.8)."""
from lib import *
from qcore import Bank
V = VERIFIED
T = V['tir']; D = V['tir_degenerate']; OX = V['oxygen_above']

def build():
    B = Bank('m8', seed=8)
    d1, d5 = T['z1']['dBT'], T['z5']['dBT']
    B.add('What is the principle of retrieving aerosol height in the thermal infrared (TIR)?',
          'The aerosol layer emits at its own temperature; temperature falls with height, so a higher layer is colder and gives a lower measured brightness temperature', ['The higher the aerosol layer, the more O₂ it absorbs', 'The delay of a laser pulse is proportional to height', 'Depolarisation increases with layer height'],
          'Guide 8.1: I ≈ B(T_s)·e^(−τ_aer) + B(T_layer)·(1 − e^(−τ_aer)); lapse rate ≈ −6.5 K/km.', 1, 'TIR', origin='goc', src='Study guide Ch.8 (checklist)')
    B.add('Write the simple expression of the measured TIR radiance with an aerosol layer (no scattering).',
          'I ≈ B(T_s)·e^(−τ_aer) + B(T_layer)·(1 − e^(−τ_aer))', ['I ≈ B(T_s)·τ_aer + B(T_layer)', 'I ≈ B(T_s) / B(T_layer)', 'I ≈ I₀·e^(+τ_aer)'],
          'The layer replaces part of the warm surface emission with its own emission at the layer temperature.', 2, 'TIR', src='Study guide 8.1')
    B.add('Two dust layers have the same AOD, one at 5 km and one at 1 km. Which gives the larger brightness-temperature depression and why?',
          'The 5 km layer, because it is colder (~6.5 K/km) so its thermal contrast with the surface is larger', ['The 1 km layer, because it is warmer and so emits more than the surface', 'Both are the same because the AOD is the same', 'The 1 km layer, because being near the ground it absorbs more O₂'],
          f'Answer key Q8(b). Simple model (T_s = 300 K, τ = 0.5, 10 µm): ΔBT = {d1:.2f} K (1 km) and {d5:.2f} K (5 km), computed in Python.', 1, 'TIR', origin='goc', src='Mock exam Q8(b)')
    B.add(f'In the simple model (T_s = 300 K, τ_aer = 0.5, 10 µm, lapse rate 6.5 K/km), what is the brightness-temperature depression of a dust layer at 5 km?',
          f'≈ {d5:.1f} K', [f'≈ {d1:.1f} K', '≈ 32.5 K (the full layer–surface temperature difference)', '≈ 0 K'],
          f'T_layer = 300 − 6.5×5 = 267.5 K; I = B(300)e^(−0.5) + B(267.5)(1 − e^(−0.5)); inverting Planck gives BT = {T["z5"]["BT"]:.2f} K → ΔBT = {d5:.2f} K. It is smaller than 32.5 K because the layer is not black (ε = 1 − e^(−τ) = 0.39).', 2, 'TIR', src='Home-made simple model, computed in Python')
    B.add('Why can the same brightness-temperature depression arise from a thin high layer or a thick low layer?',
          'Because the signal depends on τ_aer × (T_s − T_layer): AOD and height are degenerate, so they must be retrieved together', ['Because the layer temperature does not affect the signal', 'Because the infrared is insensitive to optical depth', 'Because the surface always emits as much as the layer'],
          f'Python example: a 5 km layer with τ = 0.1 gives ΔBT = {D["high_thin"]["dBT"]:.2f} K; a 1 km layer needs τ = {D["low_thick"]["tau"]:.2f} for the same ΔBT. The spectral shape in the 8–12 µm window and temperature information from the CO₂ bands are needed.', 2, 'TIR', src='Study guide 8.1; numbers computed in Python')
    B.add('When does the TIR method fail?',
          'When the thermal contrast is low (low layers, night-time inversions, cold surfaces)', ['When there is a lot of sunlight', 'When the particles are fine smoke, because then the contrast is largest', 'When the aerosol layer is very high'],
          'Answer key Q8(b); guide 8.1: it is sensitive to surface emissivity and works mainly for coarse absorbing particles (dust/ash), not for fine smoke/sulfate.', 2, 'TIR', origin='goc', src='Mock exam Q8(b)')
    B.add('What is an advantage of TIR for finding dust height?',
          'It works day and night, over bright deserts where visible methods fail, and is sensitive to coarse particles', ['It works only in daytime and clear sky', 'It does not depend on surface emissivity', 'It is more sensitive to fine smoke than to dust'],
          'Guide 8.1 (IASI, AIRS; desert dust, volcanic ash).', 1, 'TIR', src='Study guide 8.1')
    B.add('What is the principle of the O₂ A-band (~760 nm) for aerosol height?',
          'A high aerosol layer reflects photons early so the path through O₂ is shorter → weaker O₂ absorption (shallower lines)', ['A high aerosol layer emits strongly at 760 nm', 'A high aerosol layer increases O₂ absorption', 'The depth of the band does not depend on the layer height'],
          'Guide 8.2: a low layer → photons go deep → stronger O₂ absorption. The ratio of radiance in the band to the continuum (755 nm) depends on the scattering-layer pressure.', 1, 'O₂ A-band', origin='goc', src='Mock exam Q8(a)')
    B.add('Why use O₂ and not another gas to find height?',
          'Because O₂ is well mixed with a known ratio (21%, following pressure), so its absorption directly reflects the photon path', ['Because O₂ emits strongly at 760 nm', 'Because O₂ concentration varies strongly from place to place', 'Because O₂ does not absorb in this band'],
          'Answer key Q8(a): no a priori on the gas is needed; different lines/wavelengths have different absorption strengths → information on the vertical distribution.', 2, 'O₂ A-band', origin='goc', src='Mock exam Q8(a)')
    B.add('What are the advantages and limitations of the O₂ A-band?',
          'Advantages: high horizontal resolution, all aerosol types; limitations: daytime only, needs sufficient AOD, sensitive to surface albedo, single-layer assumption', ['Advantages: day and night; limitation: only coarse particles', 'Advantages: insensitive to albedo; limitation: needs night-time', 'Advantages: measures profiles directly; limitation: only over ocean'],
          'Guide 8.2: TROPOMI ALH has an accuracy of ~0.5–1 km, over ocean and dark land; AOD must exceed ~0.3–0.5.', 2, 'O₂ A-band', src='Study guide 8.2')
    B.add('What is the typical accuracy of the TROPOMI aerosol layer height (ALH)?',
          '~0.5–1 km (over ocean and dark land)', ['~10–20 km', '~50 m', '~5 K'],
          'Guide 8.2. Retrieved by optimal estimation with a full RT model, assuming a layer about 1 km thick.', 3, 'O₂ A-band', src='Study guide 8.2')
    B.add('Name another passive technique that gives plume height.',
          'Stereo/multi-angle parallax (MISR), the height dependence of UVAI, or the O₂–O₂ band at 477 nm (OMI)', ['Dual-wavelength lidar of CALIOP', 'Doppler rain radar', 'Pulse delay of GPS signals'],
          'Answer key Q8(c). MISR parallax is especially useful for fire smoke and volcanic plumes.', 1, 'Other', origin='goc', src='Mock exam Q8(c)')
    B.add('Why does aerosol height matter?',
          'To distinguish surface PM from elevated transport, long-range transport, radiative effects and aviation safety (volcanic ash)', ['Only to compute Rayleigh scattering', 'Only to calibrate lidar', 'It has no practical meaning'],
          'Opening of guide Ch.8. A passive sensor can infer height only indirectly, through effects that depend on altitude.', 1, 'Other', src='Study guide Ch.8 (introduction)')
    B.add(f'In an exponential atmosphere (scale height 7 km), which is closest to the O₂ fraction above a layer at 5 km compared with 1 km?',
          f'≈ {OX["5"]:.2f} compared with {OX["1"]:.2f}', [f'≈ {OX["1"]:.2f} compared with {OX["5"]:.2f}', '≈ 1.0 for both', '≈ 0 for both'],
          f'p(z)/p₀ = e^(−z/7) → 1 km: {OX["1"]:.3f}; 3 km: {OX["3"]:.3f}; 5 km: {OX["5"]:.3f}; 8 km: {OX["8"]:.3f} (illustrative model). Less O₂ above → shallower A-band lines.', 3, 'O₂ A-band', src='Home-made simple model (H = 7 km), computed in Python')
    B.essay('(a) Explain why the O₂ A-band (~760 nm) is suitable for retrieving aerosol or cloud height. Why O₂ and not another gas?\n(b) In the thermal infrared, a dust layer at 5 km and another at 1 km have the same AOD. Which gives the larger brightness-temperature depression and why? When does the method fail?\n(c) Name one other passive technique giving plume heights.',
            f'(a) O₂ is well mixed with a known profile (follows pressure); a high scattering layer shortens the photon path → weaker O₂ absorption; the depth/shape of the band ↔ layer pressure.\n(b) The 5 km layer: colder (~6.5 K/km) → larger thermal contrast with the surface → larger ΔBT (model: {d5:.1f} K vs {d1:.1f} K). It fails when thermal contrast is low (low layers, night inversions, cold surfaces).\n(c) Stereo/multi-angle parallax from MISR; UVAI; O₂–O₂ at 477 nm.', 3, 'Mock exam', origin='goc', src='Mock exam Q8 (2.5 points) + suggested answer')
    B.essay('Compare the principle, advantages and limitations of the two passive methods for aerosol height: thermal infrared and the O₂ A-band.',
            'TIR (IASI, AIRS; dust/ash): emission at the layer temperature, T falls with height → lower BT for a higher layer; advantages: day and night, bright deserts; limitations: needs thermal contrast, sensitive to surface emissivity, mainly coarse particles. '
            'O₂ A-band (TROPOMI, EPIC, GOSAT, OCO-2): a high layer → short O₂ path → weak absorption; advantages: high horizontal resolution, all aerosol types, known O₂; limitations: daytime only, AOD > ~0.3–0.5, sensitive to albedo, single-layer assumption. Both retrieve height together with AOD using RT/OE.', 3, 'Overview', origin='goc', src='Study guide Ch.8 (question)')
    B.essay(f'Simple model: T_s = 300 K, τ_aer = 0.5 at 10 µm, lapse rate 6.5 K/km. Compute T_layer and compare the brightness-temperature depression for layers at 1 km and 5 km.',
            f'T_layer = 300 − 6.5 z: 293.5 K (1 km) and 267.5 K (5 km). I = B(T_s)e^(−τ) + B(T_layer)(1 − e^(−τ)); inverting Planck at 10 µm gives BT = {T["z1"]["BT"]:.2f} K (1 km) and {T["z5"]["BT"]:.2f} K (5 km) → ΔBT = {d1:.2f} K and {d5:.2f} K. The higher layer gives a depression ~{d5/d1:.1f} times larger.', 3, 'TIR', src='Home-made model, numbers checked in Python')
    sl = [
        cover('Retrieving aerosol altitude with passive sensors', 'Study guide chapter 8',
              '<b>Atmospheric Remote Sensing</b> · USTH<br>Thermal infrared · O₂ A-band · other methods'),
        S('Why aerosol height matters', cards(card('Air quality', 'Separate surface PM from elevated transport.'), card('Long-range transport', 'Higher layers travel farther.'),
          card('Radiative effects', 'Height controls the radiative balance.'), card('Aviation safety', 'Volcanic ash.'), cols=4) + '<p class="note">A passive sensor infers height <b>indirectly</b>, through an altitude-dependent effect.</p>'),
        S('Two principles in one figure', figfit('f7_altitude', 'Figure 21 (study guide): (i) TIR — the layer emits at its own temperature; (ii) O₂ A-band — a higher layer leaves less O₂ above it.', 420) + '<p class="note">Both retrieve <b>height together with AOD</b> by fitting spectra with a radiative transfer model.</p>'),
        S('Thermal infrared: principle', fm('<span class="l">Layer emission</span>I ≈ B(T<sub>s</sub>) e<sup>−τ<sub>aer</sub></sup> + B(T<sub>layer</sub>) (1 − e<sup>−τ<sub>aer</sub></sup>)', 28) +
          ulb(['Lapse rate ≈ −6.5 K/km: higher layers are colder', 'Higher layer → lower brightness temperature', 'Signal ∝ τ<sub>aer</sub> × (T<sub>s</sub> − T<sub>layer</sub>)'], 33, 26)),
        S('Numerical example: layers at 1 km and 5 km', dtable(tbl(['Layer', 'T<sub>layer</sub> (K)', 'Measured BT (K)', 'ΔBT = T<sub>s</sub> − BT'], [
            ['1 km', f'{T["z1"]["Tl"]:.1f}', f'{T["z1"]["BT"]:.2f}', f'<b>{d1:.2f} K</b>'], ['5 km', f'{T["z5"]["Tl"]:.1f}', f'{T["z5"]["BT"]:.2f}', f'<b>{d5:.2f} K</b>']]), 'xl') +
          '<p class="note" style="margin-top:30px">T<sub>s</sub> = 300 K, τ = 0.5 at 10 µm. Simple model (no scattering, no H₂O); Python inverts the Planck function at 10 µm. The 5 km layer gives ~4.6 times the depression of the 1 km layer.</p>'),
        S('Degeneracy of AOD and height', dtable(tbl(['Layer', 'Height', 'τ', 'ΔBT'], [['Thin – high', '5 km', f'{D["high_thin"]["tau"]:.2f}', f'{D["high_thin"]["dBT"]:.2f} K'], ['Thick – low', '1 km', f'{D["low_thick"]["tau"]:.2f}', f'{D["low_thick"]["dBT"]:.2f} K']]), 'xl') +
          '<p class="note" style="margin-top:22px">The same depression: AOD and height must be retrieved together, using the spectral shape in the 8–12 µm window and the temperature from the CO₂ bands.</p>'),
        S('Thermal infrared: pros and cons', cards(card('Advantages', '• Day and night<br>• Over bright deserts<br>• Sensitive to coarse particles: dust, ash<br>• IASI, AIRS'), card('Limitations', '• Needs thermal contrast (fails for low layers, inversions, cold surfaces)<br>• Sensitive to surface emissivity<br>• Not suited to fine smoke or sulfate'), cols=2)),
        S('The O₂ A-band (about 760 nm)', cols(ulb(['O₂ is well mixed with a known profile', 'High aerosol layer → photons reflected early', 'Short path through O₂ → weak absorption, shallow lines', 'Low layer → strong O₂ absorption'], 28, 14),
          fm('R(λ) ≈ R<sub>aer</sub>(λ) · exp( −σ<sub>O₂</sub>(λ) N<sub>O₂</sub>(above layer) · AMF ) + …', 24) + dtable(tbl(['Height', 'O₂ above layer'], [['1 km', f'{OX["1"]:.2f}'], ['3 km', f'{OX["3"]:.2f}'], ['5 km', f'{OX["5"]:.2f}'], ['8 km', f'{OX["8"]:.2f}']]), 'mid'), flex=[1.2, 1])),
        S('Sensitivity versus layer height', figfit('f17_height_sens', 'Figure 22 (study guide): simple model — sensitivity of the TIR and O₂ A-band signals to aerosol layer height.', 420) + '<p class="note">The table before uses an exponential model with H = 7 km (illustrative).</p>'),
        S('O₂ A-band: pros and cons', cards(card('Advantages', '• No a priori on the gas needed<br>• High horizontal resolution<br>• All aerosol types, including smoke and sulfate<br>• TROPOMI ALH ~0.5–1 km'), card('Limitations', '• Daytime only<br>• Needs sufficient AOD (> ~0.3–0.5)<br>• Sensitive to surface albedo<br>• Cloud screening; single layer assumed'), cols=2)),
        S('Other passive methods', cards(card('Multi-angle parallax', 'MISR: height of fire smoke and volcanic plumes.'), card('UV aerosol index', 'UVAI depends on layer height.'), card('O₂–O₂ band at 477 nm', 'OMI: O₂–O₂ collision complex.'), cols=3)),
        S('Exam checklist — Chapter 8', chk(['TIR: emission at the layer temperature; T(z) falls → higher layer = colder = lower BT; needs thermal contrast; day and night; dust/ash', 'O₂ A-band: well-mixed O₂; higher layer → shorter path → weaker absorption; daytime; sensitive to albedo', 'Both retrieve height together with AOD using an RT model / OE'])),
        S('Key points', dul(['TIR: higher layer → colder → larger ΔBT', 'O₂ A-band: higher layer → less O₂ above', 'Height is retrieved together with AOD', 'Others: MISR, UVAI, O₂–O₂']))]
    mod = dict(id='m8', slug='08-aerosol-altitude', title='M8 · Aerosol altitude', en='Retrieving aerosol altitude with passive sensors',
               question='<ul><li>Explain the principle to derive the altitude of aerosols employing passive remote sensing from space: (i) in the thermal infrared and (ii) in the near infrared.</li></ul>',
               calcs=[('tir', 'Brightness-temperature depression vs dust-layer height')],
               checklist=['TIR: emission at layer temperature; T(z) decreases with height → higher layer = colder = lower brightness temperature; needs thermal contrast; works day/night; dust/ash.', 'NIR O₂ A-band: well-mixed O₂ absorber; higher aerosol layer shortens photon path → weaker O₂ absorption; daytime, sensitive to surface albedo.', 'Both retrieve height together with AOD by fitting spectra with an RT model / optimal estimation.'],
               summary=['Hồng ngoại nhiệt: lớp bụi phát xạ theo nhiệt độ của chính nó; nhiệt độ giảm theo độ cao → lớp càng cao càng lạnh → nhiệt độ sáng đo được càng thấp. Cần tương phản nhiệt với bề mặt; đo được cả đêm và trên sa mạc.', 'Cận hồng ngoại (dải A của O₂, 760 nm): O₂ phân bố đều và đã biết; lớp aerosol càng cao → photon bị phản xạ sớm → đường đi qua O₂ ngắn → hấp thụ O₂ yếu hơn. Chỉ ban ngày, nhạy với albedo bề mặt.', 'Cả hai đều truy hồi đồng thời độ cao và AOD bằng mô hình truyền bức xạ.'],
               sections=[
        ('Why measure height, and how?', '<p>Knowing <b>where aerosol sits vertically</b> matters for air quality (surface PM or elevated transport), long-range transport, radiative effects and aviation safety (volcanic ash). A passive sensor cannot measure height directly; it infers it <b>indirectly</b> from a physical effect that depends on altitude.</p>' +
         lfig('f7_altitude', 'Figure 21 (study guide): (i) TIR — the layer emits at its own temperature; (ii) O₂ A-band — the higher the layer, the less O₂ above it.')),
        ('(i) Thermal infrared (IASI, AIRS: mainly desert dust, volcanic ash)', '<p>In the TIR the radiance is dominated by emission. Coarse aerosols (dust, ash) absorb and emit in the 8–12 µm atmospheric window (silicate band near 9–10 µm). A dust layer replaces part of the warm surface emission by its own emission at the layer temperature:</p>' +
         eq('Emission with a layer', 'I ≈ B(T<sub>s</sub>) · e<sup>−τ<sub>aer</sub></sup> + B(T<sub>layer</sub>) · (1 − e<sup>−τ<sub>aer</sub></sup>)') +
         '<ul><li>Temperature decreases with altitude (≈ −6.5 K/km in the troposphere) → the higher the layer, the colder it is, the lower the TOA brightness temperature (larger depression relative to clear sky).</li><li>The signal depends on τ<sub>aer</sub> × (T<sub>s</sub> − T<sub>layer</sub>), so <b>AOD and height are degenerate</b>: retrieve them together, using the spectral shape in the window and the temperature profile from the CO₂ bands.</li><li>Retrieval: radiative transfer forward model (or LUT / neural network) with IR aerosol optical properties → 10 µm AOD and mean layer altitude.</li></ul>' +
         f'<div class="ex"><div class="exh">Example · numbers checked in Python (simple model, no scattering, 10 µm)</div>' +
         hx_table(['Layer', 'T<sub>layer</sub>', 'Measured BT', 'ΔBT = T<sub>s</sub> − BT'], [['1 km', f'{T["z1"]["Tl"]:.1f} K', f'{T["z1"]["BT"]:.2f} K', f'<b>{d1:.2f} K</b>'], ['5 km', f'{T["z5"]["Tl"]:.1f} K', f'{T["z5"]["BT"]:.2f} K', f'<b>{d5:.2f} K</b>']]) +
         f'<p style="margin:4px 0">T<sub>s</sub> = 300 K, τ = 0.5. The 5 km layer gives a depression ~{d5/d1:.1f} times larger. <b>Degeneracy:</b> a 5 km layer with τ = {D["high_thin"]["tau"]:.2f} gives {D["high_thin"]["dBT"]:.2f} K; a 1 km layer needs τ = {D["low_thick"]["tau"]:.2f} to give the same value.</p></div>' +
         hx_table(['Advantages', 'Limitations'], [['Day and night; over bright deserts (where visible methods fail); sensitive to coarse particles', 'Needs thermal contrast (fails when layer T ≈ surface T: low layers, night-time inversions); sensitive to surface emissivity; mainly absorbing dust/ash, not fine smoke or sulfate']], 'left') +
         '<p>Related technique: CO₂ slicing / brightness-temperature differences (11–12 µm) for volcanic ash and cloud-top height.</p>'),
        ('(ii) Near infrared: the O₂ A-band (TROPOMI ALH, EPIC, GOSAT, OCO-2)', '<p>Oxygen is well mixed (21%, following pressure). In the A-band (759–771 nm) O₂ absorption depends on the <b>photon path length</b>. Aerosols scatter photons back to space before they reach the lower atmosphere:</p>' +
         '<ul><li>High layer → photons reflected high up → short path through O₂ (little O₂ above the layer) → weak absorption (shallow lines).</li><li>Low layer → photons go deep → strong O₂ absorption.</li><li>The ratio of radiance inside the band to the continuum (755 nm), or a full spectral fit, depends on the scattering-layer pressure; lines of different strength give different penetration depths, so the band shape carries information on the vertical distribution.</li></ul>' +
         eq('Model', 'R(λ) ≈ R<sub>aer</sub>(λ) · exp( −σ<sub>O₂</sub>(λ) · N<sub>O₂</sub>(above layer) · AMF ) + …') +
         f'<div class="ex"><div class="exh">Illustration · exponential atmosphere with H = 7 km (computed in Python)</div>' + hx_table(['Layer height', '1 km', '3 km', '5 km', '8 km'], [['O₂ above the layer (relative to the ground)', f'{OX["1"]:.2f}', f'{OX["3"]:.2f}', f'{OX["5"]:.2f}', f'{OX["8"]:.2f}']]) + '</div>' +
         '<p><b>Retrieval:</b> optimal estimation with full RT (multiple scattering), retrieving layer height (or pressure) and AOD, assuming an aerosol model and a layer ~1 km thick. TROPOMI ALH: accuracy ~0.5–1 km over ocean and dark land.</p>' +
         hx_table(['Advantages', 'Limitations'], [['Known O₂ distribution (no a priori on the gas); high horizontal resolution; all aerosol types including smoke and sulfate', 'Daytime only; needs sufficient AOD (> ~0.3–0.5); very sensitive to surface albedo (bright land masks the signal); clouds must be excluded; single-layer assumption']], 'left') +
         lfig('f17_height_sens', 'Figure 22 (study guide): simple model — sensitivity of the TIR and O₂ A-band signals to aerosol layer height.') +
         '<p><b>Other passive methods:</b> stereo/multi-angle parallax (MISR, height of fire and volcanic plumes); the height dependence of UVAI; the O₂–O₂ collision complex at 477 nm (OMI).</p>')])
    return mod, sl, B
